import type { QuestionType } from "@/features/questions/domain/question";

/**
 * Evaluation submission entities — one submission is a single "form"
 * (self-evaluation or manager-evaluation) generated by the backend's
 * `POST /evaluation-cycles/{cycleId}/generate-submissions` for a respondent
 * to fill out. Mirrors `Features/EvaluationSubmissions` contracts
 * (`GET /evaluation-submissions/pending|completed|{id}`,
 * `PUT /evaluation-submissions/{id}/answers`).
 */

/**
 * Mirrors the backend `PendingSubmissionDto`, returned by both
 * `GET /evaluation-submissions/pending` and `/completed` (same shape, only
 * the filter differs server-side).
 */
export interface PendingSubmission {
  submissionId: number;
  templateTitle: string;
  cycleName: string;
  evaluatedUserName: string;
  fechaFinCiclo: string;
}

/** Mirrors the backend `SubmissionQuestionDto`. */
export interface SubmissionQuestion {
  questionId: number;
  texto: string;
  tipo: QuestionType;
  opciones: string[] | null;
  orden: number;
}

/**
 * Mirrors the backend `SubmissionDetailDto`, returned by
 * `GET /evaluation-submissions/{submissionId}`. Only carries the template's
 * questions — the backend does not expose previously saved answers through
 * any endpoint.
 */
export interface SubmissionDetail {
  submissionId: number;
  isCompleted: boolean;
  cycleName: string;
  evaluatedUserName: string;
  templateTitle: string;
  templateDescription: string | null;
  questions: SubmissionQuestion[];
  fechaFinCiclo: string;
}

/** Request body item for `PUT /evaluation-submissions/{id}/answers` (mirrors `AnswerInputDto`). */
export interface AnswerInput {
  QuestionId: number;
  /**
   * Opaque string the backend encrypts (AES-256) and stores as-is — it does
   * not interpret its shape. The frontend decides the serialization per
   * `QuestionType`: free text as-is, a rating/scale as its number-as-string,
   * a selection as a JSON-stringified array of the chosen option(s).
   */
  RawPayload: string;
}

/** Mirrors the backend generic `{ Message }` response. */
export interface SubmissionActionResult {
  message: string;
}

/**
 * Mirrors the backend `CycleSubmissionDto`, returned by
 * `GET /evaluation-cycles/{cycleId}/submissions` (Owner/Rrhh only) — one row
 * per submission of the cycle, so RRHH can see who still has to answer.
 */
export interface CycleSubmission {
  submissionId: number;
  respondentUserId: number;
  respondentUserName: string;
  evaluatedUserId: number;
  evaluatedUserName: string;
  templateTitle: string;
  isCompleted: boolean;
  submittedAt: string | null;
}
